validator:
function validate(input) {
  const [{ Enrollments = [] }] = input;
  const seen = new Set();
  for (const [student, course, grade] of Enrollments) {
    if (student === null || course === null) return 'Every enrollment needs a student_id and a course_id.';
    if (grade === null) return 'grade is never null.';
    const key = `${student}/${course}`;
    if (seen.has(key)) return `Student ${student} is enrolled in course ${course} twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const students = small ? 1 + Math.floor(rand() * 4) : 450;
  const courses = small ? 4 : 6;
  const grades = small ? [75, 80, 82, 90, 95, 95, 99] : null;
  const pairs = [];
  for (let s = 1; s <= students; s++) for (let c = 1; c <= courses; c++) pairs.push([s, c]);
  // Shuffle so rows arrive in no particular order, then keep a prefix.
  for (let i = pairs.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pairs[i], pairs[j]] = [pairs[j], pairs[i]]; }
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Enrollments = pairs.slice(0, count).map(([s, c]) => [s * 3 + 1, c * 2 + 1, grades ? grades[Math.floor(rand() * grades.length)] : 60 + Math.floor(rand() * 41)]);
  return [{ Enrollments }];
}
